     "site": "",
     "bio": "Randy Fine was born in Tucson, Arizona, and has two degrees from Harvard. He worked as a business consultant and served in the Florida House from 2016 to 2024 and the Florida Senate in 2024-2025. He has represented Florida's 6th District in Congress since April 2025, after a special election to replace Mike Waltz.",
