      "bio": "Wilton Simpson is a Republican and Florida's Agriculture Commissioner. He was born in Lakeland and ran a large egg farm in Pasco County for more than 40 years, plus an environmental services company. He served in the Florida Senate from 2012 to 2022, including two years as Senate President.",
